#: property, style property, font property, the kind of text a note names).
_DASH_GT_STYLE_PROPS = (
    ("Title", "text", "text_font_style", "text_font",
     "title, subtitle, note or caption"),
    ("Label", "text", "text_font_style", "text_font",
     "title, subtitle, note or caption"),
    ("Axis", "axis_label", "axis_label_text_font_style",
     "axis_label_text_font", "axis title"),
    ("Axis", "major_label_overrides", "major_label_text_font_style",
     "major_label_text_font", "tick label"),
    ("ColorBar", "title", "title_text_font_style", "title_text_font",
     "colour key title"),
    ("ColorBar", "major_label_overrides", "major_label_text_font_style",
     "major_label_text_font", "tick label"),
    ("Legend", "title", "title_text_font_style", "title_text_font",
     "legend key or title"),
    ("Legend", "items", "label_text_font_style", "label_text_font",
     "legend key or title"),
    ("LegendItem", "label", None, None, "legend key or title"),
    ("CustomJSTickFormatter", "args", None, None, "tick label"),
)


def _dash_gt_char(code):
    """The character ``{c code}`` draws (1-255), as twoway 19.5 writes it.

    1-127 and 160-255 are that code point (the C0 controls and DEL are kept,
    as twoway writes them raw: register A34, ratified 06oct2026 "Mirror
    twoway"); 128-159 follow cp1252, and the five codes cp1252 leaves
    undefined (129, 141, 143, 144, 157) stay the C1 code point.  0 gives
    None: ``{c 0}`` cuts the text off (``_dash_graph_text_runs``).
    """
    if code <= 0:
        return None
    if 128 <= code <= 159:
        try:
            return bytes([code]).decode("cp1252")
        except UnicodeDecodeError:
            return chr(code)
    return chr(code)


def _dash_gt_head(head, term):
    """The meaning of one ``{head<term>`` directive (*term* ``":"`` or
    ``"}"``), as twoway reads it:

    * ``("open", dim, value)`` / ``("set", dim, value)``: a style, level or
      font tag (``{bf:`` wraps text to its brace; ``{bf}`` holds to the end
      of the line).  ``{fontface "name"}`` keeps only ``[A-Za-z0-9 _-]``,
      at most 64 characters, so nothing but a name reaches the CSS.
    * ``("emit", text)``: a ``{&name}`` symbol or a ``{c #}``, ``{c 0x#}``,
      ``{char #}`` or ``{c name}`` character.
    * ``("cut",)``: ``{c 0}`` (also ``{c 00}``, ``{char 0}``; ``{c 0x0}``
      is drawn as typed, measured).
    * ``("unit",)``: an unknown ``{...}``, drawn as typed.
    * ``("frame",)``: an unknown ``{...:``, drawn as typed with its text
      still read.

    Names are case-sensitive; blanks around the head are ignored.  The
    digit caps keep int parsing linear (a 5,000-digit code is literal).
    """
    h = head.strip(" \t")
    tag = _DASH_GT_TAGS.get(h)
    if tag is not None:
        return ("open" if term == ":" else "set", tag[0], tag[1])
    m = re.fullmatch(r'fontface[ \t]+(?:"([^"]*)"|([^\s"]+))', h)
    if m:
        name = m.group(1) if m.group(1) is not None else m.group(2)
        name = re.sub(r"[^A-Za-z0-9 _-]", "", name)[:64].strip()
        return ("open" if term == ":" else "set", "font", name or None)
    if term != "}":
        return ("frame",)
    m = re.fullmatch(r"&([A-Za-z0-9]+)", h)
    if m:
        sym = _DASH_GT_SYMBOLS.get(m.group(1))
        return ("emit", sym) if sym is not None else ("unit",)
    m = re.fullmatch(r"(?:c|char)[ \t]+(\S+)", h)
    if m:
        arg = m.group(1)
        code = None
        if re.fullmatch(r"[0-9]{1,6}", arg):
            code = int(arg)
            if code == 0:
                return ("cut",)
        elif re.fullmatch(r"0x[0-9a-fA-F]{1,6}", arg):
            code = int(arg[2:], 16)
            if code == 0:
                return ("unit",)
        if code is not None:
            return ("emit", _dash_gt_char(code)) if code <= 255 else ("unit",)
        ch = _DASH_GT_CNAMES.get(arg)
        if ch is not None:
            return ("emit", ch)
    return ("unit",)


def _dash_graph_text_runs(line):
    """The styled runs twoway draws for one line of graph text: a list of
    ``(text, style, level, font)``, *style* ``"normal"``, ``"bold"`` or
    ``"italic"``, *level* -1, 0 or 1, *font* None, a CSS family or
    ``"symbol"``.

    The grammar, measured on twoway 19.5 (test/fixtures/graph_text_truth.
    json): a directive is ``{``, optional blanks, a case-sensitive name,
    optional blanks, then ``:`` (it wraps text up to its matching ``}``) or
    ``}`` (a tag then holds to the end of the line, inside the tag that
    encloses it).  An unknown ``{name}`` is literal text; an unknown
    ``{name:`` is a literal frame whose text is still read and whose ``}``
    is printed; an unclosed tag is literal; bold and italic exclude each
    other and the innermost tag wins in each of style, level and font.
    ``{c -(}`` and ``{c )-}`` draw braces that are never read again.  The
    C0/C1 control codes ``{c #}`` names are kept as those characters
    (register A34, ratified 06oct2026 "Mirror twoway").  ``{c 0}`` cuts off
    the rest of its own styled run: what follows it is dropped until the
    next tag opens, closes or is set (measured 08oct2026: ``a{c 0}b{bf:c}d``
    draws ``a``, bold ``c``, ``d``).  Other SMCL (``{hline}``, ``{cmd:}``)
    is drawn as typed (A32).  One documented difference: a symbol inside
    ``{stSymbol:}`` is drawn as itself.

    Two passes over the positions of ``{``, ``}`` and ``:`` only, no
    recursion, pieces joined once: linear in the text's length (100,000
    ``{`` in about 0.03 s).  Not idempotent: never call it on its output.
    """
    s = str(line)
    sp = [m.start() for m in re.finditer(r"[{}:]", s)]
    n = len(sp)
    # Pass 1: pair each directive with its terminator and each ':' frame
    # with the '}' that closes it.
    acts = {}
    closed = set()
    stack = []
    k = 0
    while k < n:
        p = sp[k]
        c = s[p]
        if c == "{" and k + 1 < n and s[sp[k + 1]] in ":}":
            q = sp[k + 1]
            if (s[q] == ":" and k + 2 < n and sp[k + 2] == q + 1
                    and s[q + 1] == "}"):
                # A character name ending in ':' ({c a:}, {c u:}).
                a2 = _dash_gt_head(s[p + 1:q + 1], "}")
                if a2[0] == "emit":
                    acts[p] = (a2, q + 1, 3)
                    k += 3
                    continue
            acts[p] = (_dash_gt_head(s[p + 1:q], s[q]), q, 2)
            if s[q] == ":":
                stack.append(p)
            k += 2
            continue
        if c == "}" and stack:
            closed.add(stack.pop())
        k += 1
    # Pass 2: emit text in the current state.
    sym = None
    state = ("normal", 0, None)
    frames = []
    out = []
    cut = False
    pos = 0
    k = 0
    while k <= n:
        p = sp[k] if k < n else len(s)
        if p > pos and not cut:
            t = s[pos:p]
            if state[2] == "symbol":
                if sym is None:
                    sym = str.maketrans(_DASH_GT_STSYMBOL)
                t = t.translate(sym)
            out.append((state, t))
        if k == n:
            break
        c = s[p]
        lit = None
        step = 1
        nxt = p + 1
        if c == "{" and p in acts:
            act, q, step = acts[p]
            nxt = q + 1
            kind = act[0]
            if s[q] == ":" and step == 2:
                if p in closed and kind == "open":
                    frames.append((state, False))
                    cut = False
                elif p in closed:
                    lit = s[p:q + 1]
                    frames.append((state, True))
                else:
                    lit = s[p:q + 1]
            elif kind == "set":
                cut = False
            elif kind == "emit":
                lit = act[1]
            elif kind == "cut":
                cut = True
            else:
                lit = s[p:q + 1]
            if kind in ("open", "set") and (kind == "set" or p in closed):
                if act[1] == "style":
                    state = (act[2], state[1], state[2])
                elif act[1] == "level":
                    state = (state[0], act[2], state[2])
                else:
                    state = (state[0], state[1], act[2])
        elif c == "}" and frames:
            saved, literal = frames.pop()
            if literal:
                lit = "}"
            else:
                cut = False
            state = saved
        else:
            lit = c
        if lit and not cut:
            out.append((state, lit))
        pos = nxt
        k += step
    runs = []
    for st, t in out:
        if not t:
            continue
        if runs and runs[-1][0] == st:
            runs[-1][1].append(t)
        else:
            runs.append((st, [t]))
    return [("".join(pieces), st[0], st[1], st[2]) for st, pieces in runs]


def _dash_graph_text_parts(text):
    """``(plain, style, font, flags)``: graph text as one Bokeh text draws
    it.

    Each line is read by ``_dash_graph_text_runs``.  A raised or lowered run
    is written in Unicode superscript or subscript characters when every
    character has one, else kept on the line and flagged ``"level"``.  Over
    the runs that hold a non-blank character, one style gives *style*
    (None for normal) and one font gives *font*; several give None and the
    flag ``"inline"`` (one text model has one style and font: register
    A31).  *flags* is a sorted tuple.
    """
    s = str(text)
    if "{" not in s:
        return s, None, None, ()
    styles = set()
    fonts = set()
    flags = set()
    lines = []
    for line in s.split("\n"):
        pieces = []
        for t, st, lv, ft in _dash_graph_text_runs(line):
            if lv:
                table = _DASH_GT_SUP if lv > 0 else _DASH_GT_SUB
                if all(ch in table or ch.isspace() for ch in t):
                    t = "".join(table.get(ch, ch) for ch in t)
                else:
                    flags.add("level")
            pieces.append(t)
            if t.strip():
                styles.add(st)
                fonts.add(None if ft == "symbol" else ft)
        lines.append("".join(pieces))
    style = None
    font = None
    if len(styles) == 1:
        style = next(iter(styles))
        style = None if style == "normal" else style
    elif len(styles) > 1:
        flags.add("inline")
    if len(fonts) == 1:
        font = next(iter(fonts))
    elif len(fonts) > 1:
        flags.add("inline")
    return "\n".join(lines), style, font, tuple(sorted(flags))


def _dash_graph_text(text):
    """``(text, style, font, flags)`` for a canvas sink: the translation of
    ``_dash_graph_text_parts`` with ``_dash_inert_tex`` applied last, so
    translated characters (``{c S|}{c S|}``) cannot assemble a TeX pair."""
    plain, style, font, flags = _dash_graph_text_parts(text)
    return _dash_inert_tex(plain), style, font, flags


def _dash_graph_text_plain(text):
    """The characters of graph text without its style and font (a filter
    title, a dropdown option, a tooltip row name).  Text holding no ``{`` is
    returned unchanged."""
    s = str(text)
    if "{" not in s:
        return s
    return _dash_graph_text_parts(s)[0]


def _dash_finish_text_runs(value, how):
    """``(new, changed, results)``: *value* translated as graph text, read
    as *how* says the property holds its text (``_dash_finish_text_value``'s
    four kinds, plus ``"tooltips"``), and the ``_dash_graph_text`` tuple of
    every text it translated.

    * ``"text"``: a string.  ``"map"``: a tick-override mapping (keys and
      non-string values kept).  ``"value"``: a LegendItem's fixed label,
      returned as ``{"value": new}``; a field label is left alone.
      ``"labels"``: a ``CustomJSTickFormatter``'s ``args`` holding the JSON
      tick-label map.  ``"tooltips"``: a HoverTool's ``(label, field)``
      list, each label as plain characters (DOM text), fields untouched; a
      template string is left alone.

    *value* is never mutated; ``changed`` is False when nothing changed.
    """
    if how == "text":
        if isinstance(value, str):
            r = _dash_graph_text(value)
            return r[0], r[0] != value, [r]
        return value, False, []
    if how == "map":
        if not value:
            return value, False, []
        old = dict(value)
        new = {}
        res = []
        for k, v in old.items():
            if isinstance(v, str):
                r = _dash_graph_text(v)
                res.append(r)
                new[k] = r[0]
            else:
                new[k] = v
        return new, new != old, res
    if how == "value":
        text = None
        if isinstance(value, str):
            text = value
        elif isinstance(value, dict):
            if "field" not in value and isinstance(value.get("value"), str):
                text = value["value"]
        elif isinstance(getattr(value, "value", None), str):
            text = value.value
        if text is None:
            return value, False, []
        r = _dash_graph_text(text)
        if r[0] == text:
            return value, False, [r]
        return {"value": r[0]}, True, [r]
    if how == "labels":
        if not value:
            return value, False, []
        args = dict(value)
        raw = args.get("labels")
        if not isinstance(raw, str):
            return value, False, []
        try:
            labels = json.loads(raw)
        except (TypeError, ValueError):
            return value, False, []
        if not isinstance(labels, dict):
            return value, False, []
        for v in labels.values():
            if not isinstance(v, str):
                return value, False, []
        new_map = {}
        res = []
        changed = False
        for k, v in labels.items():
            r = _dash_graph_text(v)
            res.append(r)
            new_map[k] = r[0]
            if r[0] != v:
                changed = True
        if not changed:
            return value, False, res
        args["labels"] = json.dumps(new_map)
        return args, True, res
    if how == "tooltips":
        if not isinstance(value, (list, tuple)):
            return value, False, []
        new = []
        changed = False
        for row in value:
            if (isinstance(row, (list, tuple)) and len(row) == 2
                    and isinstance(row[0], str)):
                lab = _dash_graph_text_plain(row[0])
                if lab != row[0]:
                    changed = True
                new.append((lab, row[1]))
            else:
                new.append(row)
        return (new if changed else value), changed, []
    return value, False, []


def _dash_graph_text_style(model, prop, results, fig):
    """``(kind, flags, applied)``: write the whole text's style and font
    the markup asks for onto *model*'s style properties for *prop*.

    *results* are ``_dash_graph_text`` tuples of the property's texts.

    | Row | Applied when | Otherwise |
    | Title, Label, axis title, ColorBar and Legend title | the text has a
      style or font: each that is not None | nothing |
    | Axis / ColorBar tick overrides | every label shares one (style, font)
      with one set, a FixedTicker's every tick is overridden and the axis
      is not counted | "inline" when any label is styled |
    | Legend items | every fixed label shares one (style, font) with one
      set | "inline" when any is styled |
    | LegendItem | never (its Legend decides) | -- |
    | CustomJSTickFormatter | never (its axis decides) | "inline" when
      styled |

    ``normal`` is never written: each model keeps its own default (Bokeh's
    Title is bold, its axis titles italic; S15 resets some).
    """
    import bokeh.models as _bm

    row = None
    for cls_name, p, sprop, fprop, kind in _DASH_GT_STYLE_PROPS:
        cls = getattr(_bm, cls_name, None)
        if p == prop and cls is not None and isinstance(model, cls):
            row = (cls_name, sprop, fprop, kind)
            break
    if row is None:
        return None, set(), False
    cls_name, sprop, fprop, kind = row
    flags = set()
    for r in results:
        flags.update(r[3])
    styled = [r for r in results if r[1] is not None or r[2] is not None]
    if cls_name == "LegendItem":
        return kind, flags, False
    if cls_name == "CustomJSTickFormatter":
        if styled:
            flags.add("inline")
        return kind, flags, False
    ok = False
    if prop in ("major_label_overrides", "items"):
        pairs = {(r[1], r[2]) for r in results}
        ok = bool(styled) and len(pairs) == 1
        if ok and prop == "major_label_overrides":
            ticker = getattr(model, "ticker", None)
            ticks = list(getattr(ticker, "ticks", None) or ())
            keys = set()
            for key in (getattr(model, prop, None) or {}):
                try:
                    keys.add(float(key))
                except (TypeError, ValueError):
                    pass
            counted = {id(e.get("ax")) for e in
                       (getattr(fig, "_dash_count_entries", None) or ())
                       if isinstance(e, dict)}
            ok = (isinstance(ticker, _bm.FixedTicker) and bool(ticks)
                  and all(float(t) in keys for t in ticks)
                  and id(model) not in counted)
        if not ok and styled:
            flags.add("inline")
    else:
        ok = bool(results) and bool(styled) and results[0] is styled[0]
    if not ok:
        return kind, flags, False
    if styled[0][1] is not None:
        setattr(model, sprop, styled[0][1])
    if styled[0][2] is not None:
        setattr(model, fprop, styled[0][2])
    return kind, flags, True


def _dash_graph_text_note(where, kind, flags):
    """Say once per render, *where* and *kind*, what one Bokeh text could
    not draw as twoway does; the user's text is never echoed."""
    parts = []
    if "inline" in flags:
        parts.append(f"{{bf:}}, {{it:}} or a font tag on part of a {kind} "
                     f"is drawn in that text's own style and font")
    if "level" in flags:
        parts.append(f"{{sup:}} or {{sub:}} around a character with no "
                     f"raised or lowered form in a {kind} is drawn on the "
                     f"line")
    if not parts:
        return
    _dash_warn_once(("graph_text", where, kind),
                    f"dash: {where}: " + "; ".join(parts)
                    + " (help dash, Text in graphs).", stacklevel=3)


def _dash_filter_title(label, fallback, ftype):
    """A widget's title: the resolved label, plus the documented inequality
    on a threshold slider (dash.sthlp: "varname >= slider value").

    The label of a slider, range or date widget is passed through
    :func:`_dash_inert_tex`: those are ``AbstractSlider`` titles, which
    BokehJS renders as HTML when they hold a TeX delimiter pair, and the
    label can come from a variable label the dataset carries.  A dropdown is
    a ``Select`` whose title is always a text node, so its title is left
    exactly as written.

    Graph-text markup in the label (a variable label such as
    ``{&mu} mpg``) shows its characters, without style or font tags
    (``_dash_graph_text_plain``, WP-30 P1.11b): twoway draws the label so on
    the graph, and a widget title is DOM text with one style.  The TeX
    breaker runs after the translation, so translated characters cannot
    form a pair.
    """
    raw = _dash_graph_text_plain(str(label or "").strip() or str(fallback))
    if ftype != "dropdown":
        raw = _dash_inert_tex(raw)
    if ftype == "slider" and not raw.endswith(("≥", ">=")):
        raw += " ≥"
    return raw


def _dash_finite_column(col, allow_datetime=False):
    """A float array of the non-missing values of one column.

    A datetime64 column is converted to epoch milliseconds -- the unit Bokeh
    transports datetimes in -- when *allow_datetime* is set.
    """
    if allow_datetime:
        series = pd.Series(col)
        if pd.api.types.is_datetime64_any_dtype(series):
            # Cast to an explicit millisecond unit first.  pandas 3 preserves
            # the resolution it inferred, so this column can be
            # datetime64[us] or [ns]; dividing a raw astype("int64") by a
            # fixed constant silently yields seconds for one and
            # milliseconds for the other.
            ms = series.dropna().astype("datetime64[ms]").astype("int64")
            return ms.to_numpy(dtype=float)
    arr = np.array([v for v in col if v is not None], dtype=float)
    return arr[~np.isnan(arr)]


def _dash_filter_numeric(column):
    """Whether *column* compares as NUMBERS in a dropdown (GAPS2 X1): its
    type is numeric or datetime, the one test both twins share for whether
    a dropdown value is a float or an exact text
    (:func:`_dash_dropdown_values`, :func:`_dash_dropdown_mask`,
    ``_DASH_FILTER_MASK_JS``'s ``spec.numeric``).
    """
    series = pd.Series(column)
    return bool(pd.api.types.is_numeric_dtype(series)
                or pd.api.types.is_datetime64_any_dtype(series))


def _dash_filter_rangeable(column):
    """Whether *column* can carry a range or slider filter: its type is
    numeric or datetime -- the test :func:`_dash_filter_widget` applies
    before it builds one, so the saved page refuses the variables the served
    app refuses.

    *column* is the variable over the data the filter filters.  One graph's
    rows cannot answer: a graph whose own if/in selects none has an empty
    column, and an empty column carries no type (``pd.Series([])`` is
    object).  A datetime column fails ``is_numeric_dtype`` and is filterable
    all the same (commit b25584c refused it once).
    """
    series = pd.Series(column)
    return bool(pd.api.types.is_numeric_dtype(series)
                or pd.api.types.is_datetime64_any_dtype(series))


def _dash_filter_widget(ftype, varname, column, title, value_labels=None,
                        date_kind="", max_options=None, fmt="", storage="",
                        fmt_cache=None):
    """The one filter widget both modes show for ``filter(varname, type())``.

    Args:
        ftype:        ``"dropdown"``, ``"slider"`` or ``"range"``.
        varname:      The variable.
        column:       Its values over the WHOLE dataset -- a widget's
                      categories and bounds describe the data, not whatever
                      the first graph happens to draw.
        title:        The resolved widget title.
        value_labels: ``{code: label}`` for the dropdown's display text.
        date_kind:    The variable's Stata date kind, for a clock series.
        max_options:  The most options a dropdown lists -- the
                      ``filter_options`` limit; None is its default.  A
                      caller that planned the widget with
                      ``_dash_filter_effective_type`` has said so already,
                      and the note is made once a render either way.
        fmt:          The variable's Stata display format (WP-28 S12,
                      GAPS2 E3/G6): option labels and slider labels are
                      its ``display`` text; a %tw/%tm/%tq/%th/%ty slider
                      moves over Stata's period numbers in steps of 1.
        storage:      The variable's storage type (a float writes its
                      float32 value).
        fmt_cache:    The document's formatter models, one per format
                      (:func:`_dash_fmt_tick_formatter`).

    Returns:
        ``(widget, sentinel)``.  The widget is None when the column cannot
        carry a slider or range (a string variable); the caller reports
        that.  An all-missing numeric column gives a disabled widget.
    """
    from bokeh.models import (DateRangeSlider, DateSlider, DatetimeRangeSlider,
                              RangeSlider, Select, Slider)
    series = pd.Series(column)
    is_date = bool(pd.api.types.is_datetime64_any_dtype(series))
    if ftype == "dropdown":
        vlabels = value_labels or {}
        raw_values = _dash_dropdown_values(series)
        # A per-widget sentinel absent from the data, so a real category
        # equal to the literal string "__all__" stays selectable.
        sentinel = "__all__"
        while sentinel in raw_values:
            sentinel += "_"
        limit = (_DASH_LIMITS["filter_options"][0] if max_options is None
                 else int(max_options))
        if len(raw_values) > limit:
            _dash_warn_once(("limit", "filter_options", str(varname)),
                            _dash_filter_truncation_note(
                                varname, len(raw_values), limit),
                            stacklevel=3)
            raw_values = raw_values[:limit]

        # A date's option value is its milliseconds (_dash_option_value);
        # its label is the date in the variable's own format (GAPS2 E3).
        _dfmt = _dash_date_fmt(fmt, date_kind) if is_date else ""
        _nfmt = (fmt if _dash_fmt_kind(fmt) in ("f", "g", "e")
                 else "%9.0g")

        def _label(rv):
            if rv in vlabels:
                return _dash_graph_text_plain(vlabels[rv])
            if isinstance(rv, float):
                if is_date:
                    return _dash_fmt_text(
                        _dash_stata_value_of(rv, date_kind or "td"), _dfmt)
                if rv.is_integer():
                    k = str(int(rv))
                    if k in vlabels:
                        return _dash_graph_text_plain(vlabels[k])
                # The variable's display text (GAPS2 E3, G6): %8.0gc's
                # 4,099, a float-stored 0.1's .1.
                return _dash_fmt_text(rv, _nfmt, storage or None)
            return rv

        # DISCOVERY Q26: values sharing one display text are ONE entry --
        # its value the first member's, its label the shared text -- that
        # selects every member (S17's groups; this forms them by label).
        _by_label = {}
        for rv in raw_values:
            _by_label.setdefault(str(_label(rv)), []).append(rv)

        # The option label is raw: BokehJS builds each option as
        # `option({value: label}, label)', a text node, so escaping it only
        # showed the entities (a value label `Men's' as `Men&#x27;s').  The
        # value (rv) is compared, never displayed.  Both are pinned in
        # test_label_sinks.py.
        options = [(sentinel, "All")] + [
            (members[0], text) for text, members in _by_label.items()]
        w = Select(title=title, value=sentinel, options=options)
        w._dash_sentinel = sentinel
        w._dash_ftype = "dropdown"
        # GAPS2 X1 (DISCOVERY Q26): a numeric column's dropdown compares
        # numbers as numbers; _dash_groups maps an entry's value to every
        # member sharing its display text, the value first.
        w._dash_numeric = _dash_filter_numeric(series)
        if w._dash_numeric:
            w._dash_groups = {members[0]: tuple(members)
                              for members in _by_label.values()}
        return w, sentinel
    if ftype not in ("slider", "range"):
        return None, None
    if not (pd.api.types.is_numeric_dtype(series) or is_date):
        return None, None
    _period = is_date and date_kind in ("tw", "tm", "tq", "th", "ty")
    arr = _dash_finite_column(series, allow_datetime=True)
    if _period:
        # A period kind moves over Stata's period numbers (GAPS2 E3):
        # 2000m1 is 480, and a step of 1 is one month.
        arr = _dash_period_values(arr, date_kind)
        arr = arr[np.isfinite(arr)]
    if len(arr) == 0:
        w = (RangeSlider(title=title, start=0, end=1, value=(0, 1), step=1,
                         disabled=True)
             if ftype == "range" else
             Slider(title=title, start=0, end=1, value=0, step=1,
                    disabled=True))
        w._dash_ftype = ftype
        w._dash_is_date = is_date
        if _period:
            w._dash_unit = date_kind
        return w, None
    vmin, vmax = float(arr.min()), float(arr.max())
    if vmin == vmax:
        vmax = vmin + 1.0
    if is_date:
        _tfmt = _dash_fmt_tick_formatter(
            _dash_date_fmt(fmt, date_kind or "td"),
            "" if _period else (date_kind or "td"), storage, fmt_cache)
    else:
        _tfmt = _dash_fmt_tick_formatter(
            fmt if _dash_fmt_kind(fmt) in ("f", "g", "e") else "%9.0g",
            "", storage, fmt_cache)
    if _period:
        w = (RangeSlider(title=title, start=vmin, end=vmax,
                         value=(vmin, vmax), step=1, format=_tfmt)
             if ftype == "range" else
             Slider(title=title, start=vmin, end=vmax, value=vmin, step=1,
                    format=_tfmt))
        w._dash_unit = date_kind
    elif is_date and _is_clock_kind(date_kind):
        # DateRangeSlider's step is a whole number of DAYS, so a clock
        # series spanning one day had a single reachable notch.
        step = _clock_slider_step_ms(vmin, vmax)
        w = (DatetimeRangeSlider(title=title, start=vmin, end=vmax,
                                 value=(vmin, vmax), step=step, format=_tfmt)
             if ftype == "range" else
             Slider(title=title, start=vmin, end=vmax, value=vmin, step=step,
                    format=_tfmt))
    elif is_date:
        step = _date_slider_step_days(vmin, vmax)
        w = (DateRangeSlider(title=title, start=vmin, end=vmax,
                             value=(vmin, vmax), step=step, format=_tfmt)
             if ftype == "range" else
             DateSlider(title=title, start=vmin, end=vmax, value=vmin,
                        step=step, format=_tfmt))
    else:
        # A range of whole numbers steps by 1: (vmax - vmin) / 100 gave
        # rep78, which takes the values 1..5, a step of 0.04.
        step = _whole_number_step(arr, vmax - vmin)
        w = (RangeSlider(title=title, start=vmin, end=vmax,
                         value=(vmin, vmax), step=step, format=_tfmt)
             if ftype == "range" else
             Slider(title=title, start=vmin, end=vmax, value=vmin, step=step,
                    format=_tfmt))
    w._dash_ftype = ftype
    w._dash_is_date = is_date
    return w, None


def _dash_dropdown_mask(column, value, groups=None):
    """The rows a dropdown set to *value* keeps: the Python twin of
    ``_DASH_FILTER_MASK_JS``'s dropdown branch (GAPS2 X1).

    The ONE rule, shared by both twins and pinned by
    ``test/test_dropdown_values.py::TestOneRule::test_node_and_pandas_agree``
    and ``::test_two_values_sharing_a_label_select_both``: a numeric or
    datetime column (:func:`_dash_filter_numeric`) compares NUMBERS as
    numbers -- *value* read as a float, a date's own epoch milliseconds --
    and every member of *groups*' entry for it (several distinct values
    that display under one format label, DISCOVERY Q26) keeps its rows
    too; a missing number never matches.  Any other column compares its
    EXACT text: 'nan', 'None', 'NaT', '01' and '1' are different values,
    exactly as they are listed.
    """
    if _dash_filter_numeric(pd.Series(column)):
        try:
            want = float(value)
        except (TypeError, ValueError):
            return np.zeros(len(column), dtype=bool)
        if not math.isfinite(want):
            return np.zeros(len(column), dtype=bool)
        members = (groups or {}).get(want, (want,))
        col = _dash_float_values(column, coerce=True)
        with np.errstate(invalid="ignore"):
            return np.isin(col, list(members))
    want = str(value)
    return np.array(
        ["" if v is None or (isinstance(v, float) and math.isnan(v))
         else str(v) for v in column],
        dtype=object) == want


# How often a served session may recompute.  A filter move reruns every
# aggregated layer, per by() panel, and every KPI; BUGS.md measured
# _stata_lowess at 4.8 s on 20k rows and fpfit at about 2 s on 1e6.  The
# server is one process, so while a recompute runs every other session waits,
# and a scripted websocket client can send changes as fast as it likes.  Ten
# at once lets a person click through a dropdown unhindered; two a second
# after that turns a flood into a trickle.
_DASH_EVENT_RATE = 2.0
_DASH_EVENT_BURST = 10


def _dash_event_throttle(doc, fn, rate=None, burst=None, clock=None):
    """Wrap a served ``on_change`` callback in a token bucket.

    The bucket holds *burst* tokens, starts full and refills at *rate* a
    second.  An event that finds a token runs ``fn`` at once.  One that finds
    none schedules ONE trailing call on *doc*, timed for the next token;
    every event before it runs is folded into it, and it passes the latest
    ``(attr, old, new)``.  Folding loses nothing: the filter callback reads
    every widget's current value itself, and a brush's latest selection is
    the one that counts.

    Args:
        doc:   The session's Document.  The trailing call is its timeout
               callback, so it runs under the session's lock and is dropped
               with the session.
        fn:    The callback, ``fn(attr, old, new)``.  Its exceptions
               propagate, as they would unwrapped; Bokeh logs them.
        rate:  Tokens a second; ``_DASH_EVENT_RATE`` when None.
        burst: The bucket's capacity; ``_DASH_EVENT_BURST`` when None.
        clock: Monotonic seconds; ``time.monotonic`` when None.  For tests.

    Returns:
        The throttled callback, ``(attr, old, new)``.
    """
    rate = float(_DASH_EVENT_RATE if rate is None else rate)
    burst = float(_DASH_EVENT_BURST if burst is None else burst)
    if not (rate > 0 and burst >= 1):
        # NaN fails both.  A zero rate never refills, and a bucket that
        # cannot hold a whole token never runs an event at once.
        raise ValueError("dash: an event throttle needs rate > 0 and "
                         "burst >= 1; got rate=%r, burst=%r" % (rate, burst))
    if clock is None:
        # Imported here: the served app is given this function's source and
        # imports time under another name.
        import time
        clock = time.monotonic
    tokens, stamp = burst, clock()
    pending, latest = False, None

    def _refill():
        nonlocal tokens, stamp
        now = clock()
        tokens = min(burst, tokens + (now - stamp) * rate)
        stamp = now

    def _trailing():
        nonlocal tokens, pending, latest
        _refill()
        tokens -= 1.0                       # the token it waited for
        # Cleared BEFORE fn runs: if fn raises, the next event must schedule
        # a new call, not fold into this finished one and vanish.
        args, pending, latest = latest, False, None
        fn(*args)

    def _on_change(attr, old, new):
        nonlocal tokens, pending, latest
        if pending:
            latest = (attr, old, new)
            return
        _refill()
        if tokens >= 1.0:
            tokens -= 1.0
            fn(attr, old, new)
            return
        doc.add_timeout_callback(
            _trailing, max(1, math.ceil((1.0 - tokens) / rate * 1000.0)))
        # Set once the call exists: a pending flag with nothing scheduled
        # behind it would swallow every later event.
        pending, latest = True, (attr, old, new)

    return _on_change


# ---- The toolbar ---------------------------------------------------------------

#: Every figure's tools, in this order, in both render modes (WP-21).  A
#: string, not a list of tool objects: Bokeh's figure() builds new tools from
#: it on every call, so each figure owns its own.  The served app used to
#: hand ONE list of five tool objects to every figure it drew, so every
#: toolbar in the document held the same instances.
#:
#: The drag tool active when the page opens is still pan: Bokeh activates the
#: drag tool with the lowest ``default_order`` (pan 10, lasso 12, box zoom
#: 20, box select 30), not the first one listed.  Wheel zoom is still off
#: until its button is clicked -- a wheel tool with no modifier key is not
#: auto-activated -- so scrolling the page does not zoom a figure.  No
#: crosshair: in a grid's merged toolbar it draws its lines across every
#: figure at once, and the hover tool already reads values off a figure.
_DASH_FIGURE_TOOLS = ("pan,wheel_zoom,box_zoom,box_select,lasso_select,"
                      "undo,redo,reset,save")

#: The name the save button gives the PNG of a grid: dashboard.png.  The
#: browser adds the extension from the image's type.
_DASH_SAVE_NAME = "dashboard"

#: A Stata name, which is what may name the PNG of one layout(bs) item.
#: dash.ado admits at most 22 characters for a graph; 32 is Stata's own
#: ceiling for a name, and anything else falls back to _DASH_SAVE_NAME.
_DASH_SAVE_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,31}")


def _dash_save_filename(name=None):
    """The file name, without extension, a save button writes.

    *name* when it is a Stata name -- the registered name of an item that
    ``layout(bs)`` embeds on its own -- and ``dashboard`` otherwise, which is
    also what every grid is saved as.  The name reaches the page only as a
    Bokeh model property, and the browser uses it as the download's file
    name; holding it to a Stata name keeps a hand-built spec from putting a
    path separator, a control character or a very long string there.
    """
    s = name if isinstance(name, str) else ""
    return s if _DASH_SAVE_NAME_RE.fullmatch(s) else _DASH_SAVE_NAME


def _dash_name_save(model, name=None):
    """Name the PNG the save button on *model*'s own toolbar writes.

    *model* is a figure, or a grid from ``gridplot()``, which merges every
    figure's save tool into ONE new ``SaveTool`` on the grid's toolbar.
    BokehJS exports that tool's parent -- the whole grid -- as one image.
    The merged tool has no file name, and with none BokehJS stops to
    ``prompt()`` for one, with ``bokeh_plot`` filled in.  The name is
    ``_dash_save_filename(name)``.  Returns *model*, so a call can wrap the
    ``gridplot()`` it names.
    """
    from bokeh.models import SaveTool
    filename = _dash_save_filename(name)
    toolbar = getattr(model, "toolbar", None)
    for tool in (getattr(toolbar, "tools", None) or ()):
        if isinstance(tool, SaveTool):
            tool.filename = filename
    return model


def _dash_reflow(grid, stack=True):
    """*grid*, made to fit the width it is given (TR-27.2); returns *grid*.

    A ``gridplot()`` grid sized its columns ``auto``, so no column could be
    narrower than its figure's natural minimum (about 220 px): measured in
    Chrome at a 375 px viewport, layout(3 2) kept two 220 px columns and
    the page was 440 px wide, and a by(foreign) facet under layout(bs) kept
    two 266 px panels side by side, 545 px wide -- figures offscreen,
    although layout(bs) promises that below 768 every item takes the whole
    row.  A 1 x 4 grid overflowed a 768 px window the same way.

    Now every column is an equal share of the grid (``_DASH_BS_TRACK``,
    minmax(0, 1fr)), so a grid can never be wider than its container, and
    a grid of *n* columns whose width is under n x ``_DASH_MIN_COLUMN_PX``
    stacks its cells into one column, each the grid's full width, in
    reading order.  The test is on the grid's own width (a CSS container
    query), not the window's, so a facet grid inside a narrow cell or tab
    stacks too.  The served ``layout(bs)`` GridBox, whose spans already
    shrink, stacks below ``_DASH_BS_STACK_BELOW_PX`` of window, the saved
    layout(bs) page's own breakpoint.  A Row wraps its children onto
    further lines (the filter bar was 411 px at 375); with *stack* (the
    filterposition(left) row) it also stacks them below that breakpoint,
    each at its own height -- a Bokeh row child's flex basis is 0, and
    stacked without ``flex: 0 0 auto`` the grid collapsed to 0 px tall.
    Nothing here reads user input: the CSS is built from integers.

    A ``layout(bs)`` GridBox gets one more stylesheet after this: WP-28
    E14's ``_dash_bs_grid`` appends ``_dash_bs_grid_css()`` to the stacking
    rule this function adds, so the grid takes the saved page's md half
    rows and KPI cell heights between 768 and 991 px too.
    """
    from bokeh.models import GridBox, InlineStyleSheet, Row
    below = int(_DASH_BS_STACK_BELOW_PX) - 0.02
    if isinstance(grid, GridBox):
        css = ("@media (max-width: %.2fpx) { :host { display: flex "
               "!important; flex-direction: column !important; } }" % below)
    elif isinstance(grid, Row):
        css = ":host { flex-wrap: wrap !important; }"
        if stack:
            css += (" @media (max-width: %.2fpx) { :host { flex-direction: "
                    "column !important; height: auto !important; } "
                    ":host > * { flex: 0 0 auto; } }" % below)
    else:
        ncols = 1
        for child in (getattr(grid, "children", None) or ()):
            try:
                ncols = max(ncols, int(child[2]) + 1)
            except (TypeError, ValueError, IndexError):
                continue
        grid.cols = _DASH_BS_TRACK
        if ncols < 2:
            return grid
        css = (":host { container-type: inline-size; } "
               "@container (max-width: %.2fpx) { :host > .bk-GridBox { "
               "display: flex; flex-direction: column; } }"
               % (ncols * int(_DASH_MIN_COLUMN_PX) - 0.02))
    grid.stylesheets = list(grid.stylesheets) + [InlineStyleSheet(css=css)]
    return grid


# ---- The document: order, cells, tabs, header ----------------------------------

def _dash_layout_order(registry, graphs, kpis):
    """Display order of the registered items: the registry, as typed.

    ``dash.ado`` appends every name() -- graph or KPI -- to ONE registry in
    the order the user issued it, so that order is the user's.  A spec with
    no registry (hand-built) falls back to graphs then KPIs in spec order.
    A registered name that is neither is dropped; a graph or KPI the
    registry omits is appended, so nothing vanishes.

    The saved renderer used to put every KPI first whatever the registry
    said -- a Bootstrap hero-row policy that had leaked into every layout
    -- so the same spec placed a card above its graph when saved and below
    it when served.
    """
    gnames = [str((g.get("graph_options") or {}).get("name")
                  or g.get("name") or "") for g in graphs]
    knames = [str(k.get("name") or "") for k in kpis if k.get("name")]
    # An immediate render -- `dash scatter mpg weight, saving()' -- writes
    # ONE graph with no name and no registry; its figure is keyed '' and
    # must still be placed.  Dropping the empty name here produced a
    # saved dashboard with no figure and rc 0, which the certification
    # suite caught and the Python suite, whose every spec is named, did not.
    known = gnames + knames
    order = [n for n in str(registry or "").split() if n in known]
    seen = set(order)
    for n in known:
        if n not in seen:
            order.append(n)
            seen.add(n)
    return order


def _dash_auto_grid_cols(n, figures=None):
    """Columns of the ``layout(auto)`` grid for *n* items, in both modes.

    ``ceil(sqrt(n))``, aware of the proportions the figures have: when any
    figure in *figures* (``{key: figure}``) is at least three times as wide
    as it is tall every item takes a row of its own, and at 1.8 times the
    grid has one column fewer, so a dashboard of wide figures is not
    squeezed into narrow cells.  The saved page applied this and the served
    app did not: measured at 4ede074, four graphs drawn xsize(12) ysize(3)
    were one column of four saved and a 2 x 2 grid served.

    Args:
        n:       How many items the grid holds.
        figures: The dashboard's figures; ``aspect_ratio`` is width/height.

    Returns:
        The column count, at least 1.
    """
    if n <= 0:
        return 1
    cols = math.ceil(math.sqrt(n))
    ratios = [float(f.aspect_ratio) for f in (figures or {}).values()
              if getattr(f, "aspect_ratio", None)]
    if ratios:
        widest = max(ratios)
        if widest >= 3.0:
            cols = 1
        elif widest >= 1.8:
            cols = max(1, cols - 1)
    return max(1, cols)


def _dash_kpi_keys(name, kpi_divs):
    """The ``kpi_divs`` keys one registered KPI owns: its own card, or none.

    A KPI is one card in both modes.  The saved renderer used to split one
    into per-panel cards ``name__by__0``, ``name__by__1``, ... and this
    found them by prefix -- a prefix a KPI named ``g2__by__0`` also
    matched, making graph g2 a card.  Neither can happen now.
    """
    return [name] if name in kpi_divs else []


def _dash_link_names(link, graph_names):
    """The graphs ``link()`` ties together, by one rule in both modes: the
    names it gives, or every graph when one of them is ``_all``.

    dash.ado takes ``link(_all)`` alone, and refuses it beside other names.
    The saved renderer expanded ``_all`` wherever it stood and the served
    app only when it stood alone, so ``link(_all g2)`` linked every graph
    when saved and none when served (measured 23sep2026).  Names may be
    separated by ``;``, as older specs wrote them.
    """
    if isinstance(link, (list, tuple)):
        names = [str(x) for x in link]
    else:
        names = str(link or "").replace(";", " ").split()
    if "_all" in names:
        return [n for n in graph_names if n]
    return names


def _dash_excluded(key, excluded, owner_of):
    """True when ``filter(..., exclude())`` names *key*: the graph it
    belongs to, or the by() graph whose panel it is (*owner_of* maps a
    panel's key to its graph's name).

    A by() graph's panels are keyed ``g1__by__0``, ``g1__by__1``, ..., and
    both modes matched exclude(g1) against those keys alone, so an unlinked
    by() graph's panels were filtered as though nothing had been excluded
    (measured 23sep2026: 5 and 5 rows became 3 and 1 on a price move).
    """
    return key in excluded or owner_of.get(key) in excluded


def _dash_filter_applies(target, exclude, owner_of, members=None):
    """True unless ``filter(..., exclude())`` removes *target* (GAPS2 E2).

    With *members* -- a link group's shared source draws for several
    graph names -- true unless EVERY member is excluded: the group is
    filtered by a filter unless every graph of the group is excluded from
    it (dash.sthlp), so *target* itself is not consulted when *members* is
    given.  Without it, true unless :func:`_dash_excluded` removes
    *target* alone (a graph, a by() panel through *owner_of*, a KPI card,
    an aggregate or a derived layer -- each answers to its own single
    name).
    """
    if members:
        return not all(_dash_excluded(m, exclude, owner_of) for m in members)
    return not _dash_excluded(target, exclude, owner_of)


def _dash_widgets_for(target, widgets, owner_of, members=None):
    """The filter widgets that apply to *target* (GAPS2 E2): those whose
    ``exclude()`` does not remove it, tested by :func:`_dash_filter_applies`
    with each widget's own ``_dash_exclude`` list.  The served twin of the
    saved page's per-target ``use`` index list.
    """
    return [w for w in widgets
            if _dash_filter_applies(
                target, getattr(w, "_dash_exclude", []), owner_of, members)]


# ---- A link group's views, after a filter move (served) -----------------------
#
# Every member of a link() group draws from ONE ColumnDataSource.  A member
# that must not draw all of it -- a by() panel, a graph or a layer with its
# own if()/in() -- draws through a CDSView whose IndexFilter holds positions
# in that source (_dash_layer_source).  The served recompute used to write
# each linked graph's and each panel's own filtered rows into the shared
# source in turn, so whichever was written last decided what every linked
# graph showed, and it never recounted a view's positions against the rows
# the source then held: measured 23sep2026 on sysuse auto, link(g1 g2) with
# g1 by(foreign) and a price range of 5000-8000 drew panels of 9 and 0 rows
# and g2 9, where the saved page draws 14, 9 and 23.  The saved page's
# callback (_FILTER_JS) writes the shared source once with the rows every
# filter keeps and rebuilds each view from the rows it owns; these helpers
# do the same when served.

def _dash_view_positions(position_of, members):
    """Where a view's own rows now sit in the source it draws from.

    A view owns a fixed set of rows -- those its graph's qualifier, its by()
    group and its layer's qualifier select from the whole dataset -- and a
    filter move rewrites the source with fewer, so its positions are counted
    again against the rows the source holds now.

    Args:
        position_of: ``{row label: position}`` for the rows the source holds
                     now.
        members:     The row labels the view owns.

    Returns:
        Ascending positions.  An owned row the source no longer holds -- a
        filter dropped it -- is not drawn.
    """
    return sorted(position_of[m] for m in members if m in position_of)


def _dash_linked_views(figures, source):
    """Each view over *source* in *figures*, with the rows it owns.

    Read once, before any filter moves, while *source* still holds every row:
    a view's positions then name its own rows through the source's ``index``
    column (row labels).  Only IndexFilter views are listed, the only kind
    the served app builds (_dash_layer_source).  A filter several renderers
    draw through is listed once.

    Args:
        figures: The figures, each with ``.renderers``.
        source:  The link group's shared ColumnDataSource.

    Returns:
        ``[(IndexFilter, frozenset of row labels)]``.
    """
    labels = list(source.data.get("index", []))
    n = len(labels)
    out, seen = [], set()
    for fig in figures:
        for r in getattr(fig, "renderers", []):
            if getattr(r, "data_source", None) is not source:
                continue
            flt = getattr(getattr(r, "view", None), "filter", None)
            if not isinstance(flt, IndexFilter) or flt.indices is None:
                continue
            if id(flt) in seen:
                continue
            seen.add(id(flt))
            out.append((flt, frozenset(labels[i] for i in flt.indices
                                       if 0 <= i < n)))
    return out


def _dash_refresh_linked(source, frame, views, snapshot=None, pos_of=None,
                         need=None):
    """Write one filter move's rows into a link group's source, once, and
    point every view over it at the rows it owns.

    *frame* is the rows every active filter keeps: the whole dataset masked,
    before any graph's if()/in() or by() group -- those live in the views.
    A graph drawing the source without a view draws all of it.

    The views are written before the data when the source shrinks and after
    it when it grows: the browser applies the changes in order, and a view
    naming a row past its source's end is ignored with an out-of-bounds
    warning in the console.

    Args:
        source:   The shared ColumnDataSource; its ``index`` column is the
                  row labels.
        frame:    The filtered DataFrame, indexed by row label.
        views:    ``_dash_linked_views``' list.
        snapshot: ``{column: values}`` the source held before any move; a
                  column *frame* does not carry is taken from it by row.
        pos_of:   ``{row label: position in snapshot}``.
        need:     The page plan's ``need`` (WP-29 P0.11): a column written
                  from *frame* is blanked on every row it does not flag
                  (``_dash_embed_values``), so a move never sends a cell
                  the page does not hold.
    """
    labels = list(frame.index)
    old_n = len(next(iter(source.data.values()), [])) if source.data else 0
    new_data = {}
    rows = None
    for col in list(source.data):
        if col == "index":
            new_data[col] = labels
        elif col in frame.columns:
            if need is not None and col in need:
                new_data[col] = _dash_column_values(
                    _dash_embed_values(frame[col], need[col]))
            else:
                new_data[col] = _dash_column_values(frame[col])
        else:
            if rows is None:
                at_snap = pos_of or {}
                rows = [at_snap.get(lbl, -1) for lbl in labels]
            orig = (snapshot or {}).get(col, [])
            new_data[col] = [orig[i] if 0 <= i < len(orig) else None
                             for i in rows]
    at = {lbl: i for i, lbl in enumerate(labels)}
    positions = [_dash_view_positions(at, members) for _flt, members in views]

    def _point():
        for (flt, _members), pos in zip(views, positions):
            flt.indices = pos

    if len(labels) < old_n:
        _point()
        source.data = new_data
    else:
        source.data = new_data
        _point()


def _dash_own_redrawn_views(figures, redrawn_ids):
    """Give each renderer that draws a REDRAWN source through a view a filter
    of its own, and return those filters by source.

    A linked layer's mapper can draw from a copy of the shared source -- a
    line in its join order, connected's line, a jittered scatter, dropline's
    segments -- and keep the view it was handed.  A filter move redraws the
    copy from the layer's own filtered rows, which are exactly the rows to
    draw, so after one its view selects every row.  The view is often the
    very one a renderer on the shared source draws through (connected's
    markers), whose positions a move recounts for that source, so each
    renderer here gets a copy first: a line exclude() protects, never
    redrawn, then keeps the positions it was drawn with.  Called once,
    before any move.

    Args:
        figures:     The figures, each with ``.renderers``.
        redrawn_ids: ``id()`` of every source the recompute redraws.

    Returns:
        ``{id(source): [IndexFilter, ...]}``.
    """
    out = {}
    for fig in figures:
        for r in getattr(fig, "renderers", []):
            src = getattr(r, "data_source", None)
            if src is None or id(src) not in redrawn_ids:
                continue
            flt = getattr(getattr(r, "view", None), "filter", None)
            if not isinstance(flt, IndexFilter) or flt.indices is None:
                continue
            own = IndexFilter(indices=list(flt.indices))
            r.view = CDSView(filter=own)
            out.setdefault(id(src), []).append(own)
    return out


# ---- An unlinked layer's source, after a filter move (served) ----------------
#
# An unlinked layer draws from a ColumnDataSource of its own rows: the graph's
# qualifier, the by() panel's group, the layer's own if()/in() -- counted over
# the whole dataset at the first draw (_dash_layer_frame) -- and without the
# rows whose plotted variables are missing (_dash_layer_source).  The served
# recompute used to write into it every row the move kept for the graph or
# panel, so a layer's own qualifier was lost at the first move: measured
# 24sep2026 on sysuse auto, `(scatter mpg weight in 40/60) (lfit mpg weight
# in 40/60)' with the dropdown on Foreign drew all 22 foreign cars where
# Stata's `count if foreign == 1 in 40/60' and the saved page give 8.  A
# column the layer derives -- the marker-label text, a colour bin -- was
# taken from the source's snapshot at the ROW LABEL, read as a position, so
# under any qualifier its values belonged to other rows and the column came
# out shorter than the rest (Bokeh: "columns must be of the same length").
# The saved page's callback (_FILTER_JS) filters each source's own snapshot
# by row identity; this does the same when served.

def _dash_refresh_unlinked(source, frame, snapshot):
    """Write one filter move's rows into an unlinked layer's source: the rows
    of its own that *frame* keeps, by identity.

    The rows a source was built with are its ``index`` column (row labels)
    in the snapshot taken before any move; they already carry the layer's
    own if()/in(), counted over the whole dataset once, at the first draw.
    A move keeps those of them that *frame* holds, in the source's own
    order, so a qualifier, a by() panel's group and a dropped missing value
    all survive it.  A column of *frame* is read from *frame*; a column the
    layer derived (the marker-label text, a colour bin) is read from the
    snapshot at the row's own position, so every column keeps one value per
    row.  A source built without row labels (a graph's placeholder) is
    written with *frame*'s rows, as before.

    Args:
        source:   The layer's ColumnDataSource.
        frame:    The rows the move keeps for this source's graph or panel:
                  the dataset masked by every active filter, a by() panel's
                  group and the graph's if()/in(), indexed by row label.
        snapshot: ``{column: values}`` the source held before any move.

    Returns:
        The data written.
    """
    snapshot = snapshot or {}
    ids = snapshot.get("index")
    if ids is None:
        rows, pos = frame, None
    else:
        keep = pd.Index(ids).isin(frame.index)
        pos = [int(p) for p in np.flatnonzero(keep)]
        rows = frame.loc[[ids[p] for p in pos]]
    labels = rows.index.tolist()
    new_data = {}
    for col in list(source.data):
        if col == 'index':
            new_data[col] = labels
        elif col in rows.columns:
            new_data[col] = _dash_column_values(rows[col])
        else:
            orig = snapshot.get(col, [])
            n = len(orig)
            # Without row labels the source is the dataset in order, and a
            # label is its position (the placeholder's case, unchanged).
            at = pos if pos is not None else labels
            new_data[col] = [orig[i] if 0 <= i < n else None for i in at]
    source.data = new_data
    return new_data


def _dash_keep_jitter(new_data, snapshot):
    """Keep each kept row's jittered point where the first draw put it.

    A served filter move redraws a jittered scatter through its mapper from
    the kept rows, and ``_apply_jitter`` then drew fresh noise over fewer
    rows -- a narrower range, a shorter draw -- so every kept point moved.
    The saved page keeps a move's rows of the jittered copy by row id and
    moves none (``_FILTER_JS``).  Stata jitters once, when it draws; a
    filter is dash's own, and a point should not wander when it is kept.
    Each ``__dash_xjit``/``__dash_yjit`` column of *new_data* takes the value the
    snapshot held for the same row label; a row the snapshot never held
    keeps its fresh value.

    Args:
        new_data: The redrawn source's ``{column: values}``; changed in
                  place.  Its ``index`` column holds the rows' labels.
        snapshot: ``{column: values}`` the live source held before any move.

    Returns:
        *new_data*.
    """
    snapshot = snapshot or {}
    ids, labels = snapshot.get("index"), new_data.get("index")
    if ids is None or labels is None:
        return new_data
    pos = {}
    for i, lab in enumerate(ids):
        pos.setdefault(lab, i)
    for col in list(new_data):
        if not (col.startswith(_DASH_JITTER_X) or col.startswith(_DASH_JITTER_Y)):
            continue
        orig = snapshot.get(col)
        if orig is None:
            continue
        fresh = list(new_data[col])
        new_data[col] = [
            orig[pos[lab]] if lab in pos and pos[lab] < len(orig) else v
            for lab, v in zip(labels, fresh)]
    return new_data


def _dash_facet_cols(gopts, n_panels):
    """cols(#) from by() first, then the by_cols key, then ceil(sqrt(n)) --
    and never more columns than there are panels.

    Nothing upstream bounds #, and a column past the last panel draws
    nothing: gridplot() skips the None the last row is padded with.  The
    padding was built all the same -- cols(30000000) of four panels took
    1.8 s and 237 MB, cols(1000000000) about a minute and 8 GB, for one
    render and again for every served session.
    """
    n_by = _dash_parse_by((gopts.get("by") or ""), warn=False)[1]
    try:
        n_key = int(gopts.get("by_cols", "0") or 0)
    except (ValueError, TypeError):
        n_key = 0
    n = n_by or n_key
    if n <= 0:
        n = min(n_panels, max(1, math.ceil(math.sqrt(n_panels))))
    return max(1, min(n, n_panels))


def _dash_graph_options_of(graphs, name):
    """The graph_options of the graph the layout places under *name*.

    The key is ``_dash_layout_order``'s: the graph's name(), else its
    top-level name, else '' -- the one-line form's graph, which has no
    name.  Every grid used to match graph_options' own "name" alone, so
    the one-line graph's options were never found and its by(, cols(#))
    was ignored: `dash scatter mpg weight, by(foreign, cols(1))
    saving(f)' drew its panels side by side (WP-27).  The first graph with
    the key wins, as it did.  Malformed entries are skipped.
    """
    for g in graphs or ():
        if not isinstance(g, dict):
            continue
        go = g.get("graph_options")
        go = go if isinstance(go, dict) else {}
        if str(go.get("name") or g.get("name") or "") == str(name):
            return go
    return {}


def _dash_layout_cell(name, figures, facet_map, kpi_divs, gopts_of):
    """The ONE renderable a registered name owns, or None.

    A faceted graph is one cell: its panels in a sub-grid that honours
    by(, cols(#)).  A plain graph is its figure.  A KPI is its card.  The
    grid AND the tab panels call this,
    in both modes -- the saved tabs used to flatten a faceted graph's
    panels into the tab's own grid, ignoring cols(), while the saved grid
    and the served app nested them.  The sub-grid keeps a toolbar of its
    own, whose save button writes dashboard.png like every grid's.
    """
    if name in facet_map:
        figs = [figures[fk] for fk, _ in facet_map[name] if fk in figures]
        if not figs:
            return None
        cn = _dash_facet_cols(gopts_of(name) or {}, len(figs))
        rows = [figs[i:i + cn] for i in range(0, len(figs), cn)]
        while len(rows[-1]) < cn:
            rows[-1].append(None)
        grid = gridplot(rows, sizing_mode="stretch_width")
        # by()'s overall text above and below the panels (WP-30 P1.15a).
        _dash_by_frame_grid(grid, getattr(figs[0], "_dash_by_chrome", None),
                            cn)
        return _dash_name_save(_dash_reflow(grid))
    if name in figures:
        return figures[name]
    return kpi_divs.get(name)


def _dash_parse_tabs(tabs_str, all_names, limit=None):
    """``'Title: a b / Title2: c'`` -> ``[(title, [names])]``, or None.

    Tab titles are the user's text, verbatim.  Only registered names are
    accepted, so a tabs() option cannot place something that was never
    registered.  At most *limit* tabs are kept (the ``tabs`` limit, its
    default when None): a name may sit in any number of tabs, so tabs()
    alone could ask for thousands -- 3,000 took 14.4 s -- whatever the
    registry holds.
    """
    if limit is None:
        limit = _DASH_LIMITS["tabs"][0]
    if not tabs_str or not str(tabs_str).strip():
        return None
    valid = set(all_names)
    result = []
    for i, segment in enumerate(str(tabs_str).split("/")):
        segment = segment.strip()
        if not segment:
            continue
        if ":" in segment:
            raw_title, _, items_str = segment.partition(":")
            title = raw_title.strip()
            items = [x.strip() for x in items_str.split() if x.strip()]
        else:
            items = [x.strip() for x in segment.split() if x.strip()]
            title = "Tab %d" % (i + 1)
        safe = [x for x in items if x in valid]
        if safe:
            result.append((title, safe))
    if len(result) > limit:
        _dash_warn_once(
            ("limit", "tabs"),
            f"dash: tabs() has {len(result):,} tabs, more than the "
            f"{limit:,} a dashboard draws; the first {limit:,} are drawn. "
            f"{_dash_limit_hint('tabs', 'draw more', start=True)}.",
            stacklevel=3)
        result = result[:limit]
    return result or None


def _dash_tab_panels(tabs_spec, cell_of):
    """``(Tabs or None, registered names placed)`` from ``[(title, [names])]``.
    Each tab is a ceil(sqrt(n)) grid of the cells its names own, with its
    own toolbar, whose save button writes that tab's grid to dashboard.png."""
    from bokeh.models import TabPanel, Tabs
    panels, placed = [], set()
    for title, names in (tabs_spec or []):
        items = [c for c in (cell_of(n) for n in names) if c is not None]
        if not items:
            continue
        placed.update(names)
        cn = max(1, math.ceil(math.sqrt(len(items))))
        rows = [items[i:i + cn] for i in range(0, len(items), cn)]
        while len(rows[-1]) < cn:
            rows[-1].append(None)
        panels.append(TabPanel(
            child=_dash_name_save(_dash_reflow(gridplot(rows, sizing_mode="stretch_width"))),
            title=title))
    if not panels:
        return None, placed
    return Tabs(tabs=panels, sizing_mode="stretch_width"), placed


# ---- layout(bs): one reading of the rows, for both render modes ------------

def _dash_is_bs_layout(layout_opt):
    """True when *layout_opt* asks for the Bootstrap grid.

    Bootstrap layouts start with the literal token ``bs`` (case-insensitive),
    optionally followed by a colon and an explicit column-span
    specification::

        layout(bs)                              # auto layout
        layout(bs: k1=3 k2=3 / s1=8 h1=4)       # explicit layout

    A value that reads whole as placements or a grid is not one, whatever
    its first letters: every reader took any value starting with ``bs``
    for the Bootstrap form, so ``layout(bsales:1,1 g2:1,2)`` -- a graph
    named bsales, placed -- was refused by dash.ado and drawn as
    layout(bs) by both modes (measured 23sep2026).  dash.ado's Mata
    ``_dash_layout_refusal`` reads it by the same rule.
    ``_dash_layout_check`` has already made any other value that starts with
    ``bs`` plain ``bs``.
    """
    text = str(layout_opt or "").strip(_DASH_ASCII_BLANKS)
    return text[:2].lower() == "bs" and _dash_layout_cells(text) is None


def _dash_auto_bs_layout(all_names, kpi_names, figures=None):
    """Generate an automatic Bootstrap layout.

    KPI cards are placed in a first row with equal column spans (up to 4 per
    row).  Graphs fill the rows after them: a graph at least 2.5 times as
    wide as it is tall takes a row of its own; of the rest, one alone takes
    the whole row, and otherwise they go two to a row (``col-6`` each) --
    three (``col-4``) when there are five or more and none is at least 1.8
    times as wide as it is tall.

    Only the names in *all_names* are laid out.  A KPI card in *kpi_names*
    that *all_names* does not hold -- one tabs() placed, which both modes
    leave out of the grid -- used to get a row anyway: the saved page drew
    the card in its tab and again, full width, in the grid.

    Args:
        all_names:  All dashboard element names in display order.
        kpi_names:  The names of *all_names* that are KPI cards.
        figures:    ``{figure key: figure}``; a graph's aspect ratio decides
                    how many share a row.  None reads every ratio as 0.

    Returns:
        A list of rows, each row being a list of ``(name, col_span)`` tuples.
    """
    _present = set(all_names)
    kpi_names = [n for n in kpi_names if n in _present]
    graph_names = [n for n in all_names if n not in kpi_names]
    rows: list[list[tuple[str, int]]] = []

    # ---- KPI row(s) ----
    if kpi_names:
        n_kpis = len(kpi_names)
        # A KPI card has no aspect ratio to derive a count from -- four
        # per row is a legibility judgement, not a derivable quantity, so
        # it is a named constant rather than a bare literal.
        per_row = min(n_kpis, _MAX_KPIS_PER_ROW)
        span = max(1, 12 // per_row)
        for i in range(0, n_kpis, per_row):
            chunk = kpi_names[i : i + per_row]
            rows.append([(name, span) for name in chunk])

    # ---- Graph row(s) ----
    if graph_names:
        n_graphs = len(graph_names)
        # Derived from each figure's OWN proportions, not from the
        # count alone and not from the widest figure on the dashboard: a
        # panel wide enough to need a full row should take one without
        # pushing every other graph onto a row of its own.
        def _ar_of(nm):
            _f = (figures or {}).get(nm)
            _a = getattr(_f, "aspect_ratio", None) if _f else None
            return float(_a) if _a else 0.0

        _wide = [n for n in graph_names if _ar_of(n) >= 2.5]
        _rest = [n for n in graph_names if n not in _wide]

        for name in _wide:
            rows.append([(name, 12)])

        if _rest:
            n_rest = len(_rest)
            if n_rest == 1:
                per_row = 1
            elif max((_ar_of(n) for n in _rest), default=0.0) >= 1.8:
                per_row = min(2, n_rest)
            elif n_rest <= 4:
                per_row = 2
            else:
                per_row = 3
            span = max(1, 12 // per_row)
            for i in range(0, n_rest, per_row):
                chunk = _rest[i : i + per_row]
                rows.append([(name, span) for name in chunk])

    return rows if rows else [[(n, 12 // max(1, len(all_names))) for n in all_names]]


def _dash_parse_bs_layout(layout_opt, all_names, kpi_names, figures=None):
    """Parse a Bootstrap layout string into rows of ``(name, col_span)`` pairs.

    Syntax::

        bs                              # automatic layout
        bs: name=N ...                  # explicit; / separates rows
        bs: k1=3 k2=3 / s1=8 h1=4

    Column spans are integers in ``[1, 12]``.  Items missing from the spec
    that are present in *all_names* are appended as full-width (``col-12``)
    entries after the last explicit row.

    The saved page and the served app both lay their grid out from what this
    returns: the saved page as rows of ``db-col-lg-N`` cells, the served app
    through ``_dash_bs_grid``.

    Security:
        Name tokens are validated against *all_names*; unknown tokens are
        dropped here.  Span values are clamped to ``[1, 12]``.  Both are
        reported before this runs, by ``_dash_layout_check`` (dash.ado
        refuses them).

    Args:
        layout_opt:  The raw ``layout()`` option string, must start with ``bs``.
        all_names:   The names the grid holds, in display order: the
                     registry as typed, less what tabs() placed.
        kpi_names:   The KPI card names, for the automatic layout.
        figures:     ``{figure key: figure}``, for the automatic layout.

    Returns:
        List of rows, each a list of ``(name, col_span)`` tuples.
    """
    stripped = layout_opt.strip()
    # Pure "bs" or "bs " — auto layout
    if re.match(r"^bs\s*$", stripped, re.IGNORECASE):
        return _dash_auto_bs_layout(all_names, kpi_names, figures)

    # Explicit: "bs: <spec>"
    m = re.match(r"^bs\s*:\s*(.+)$", stripped, re.IGNORECASE | re.DOTALL)
    if not m:
        return _dash_auto_bs_layout(all_names, kpi_names, figures)

    spec_str = m.group(1)
    valid_names = set(all_names)
    placed: set[str] = set()
    rows: list[list[tuple[str, int]]] = []

    for row_str in spec_str.split("/"):
        row: list[tuple[str, int]] = []
        for token in row_str.split():
            token = token.strip()
            if not token:
                continue
            if "=" in token:
                parts = token.split("=", 1)
                name = parts[0].strip()
                try:
                    span = max(1, min(12, int(parts[1].strip())))
                except (ValueError, TypeError):
                    span = 6
            else:
                name = token
                span = 6  # default span when not specified
            # Security: only accept names present in the registry -- and
            # each once, at its first place.  A repeated name was placed
            # again for every repeat: 100,000 repeats made an 18.1 MB saved
            # page of duplicate element ids (WP-21, test_adversarial_matrix).
            if name in valid_names and name not in placed:
                row.append((name, span))
                placed.add(name)
        if row:
            rows.append(row)

    # Append any names not mentioned in the spec as full-width rows
    unplaced = [n for n in all_names if n not in placed]
    for name in unplaced:
        rows.append([(name, 12)])

    return rows if rows else _dash_auto_bs_layout(all_names, kpi_names, figures)


def _dash_bs_grid_cells(rows):
    """``[(name, row, col, row_span, col_span), ...]`` for bs *rows*.

    Where the saved page's markup puts each cell at its large breakpoint:
    every bs row is a ``.db-row{flex-wrap:wrap}`` of ``db-col-lg-N`` cells,
    so it starts a new line, and within it the cells run left to right and
    a cell whose span would carry the row past 12 columns starts the next
    line -- flex-wrap.  A row with no cells takes no line; the saved page
    writes none for it.  Rows and columns are 0-based, as a GridBox reads
    them.

    Args:
        rows: What ``_dash_parse_bs_layout`` returns.

    Returns:
        One ``(name, row, col, 1, span)`` a cell, in the order given.
    """
    cells = []
    line = 0
    for bs_row in rows or []:
        used = 0
        for name, span in bs_row:
            span = min(_DASH_BS_COLUMNS, max(1, int(span)))
            if used + span > _DASH_BS_COLUMNS:
                line += 1
                used = 0
            cells.append((name, line, used, 1, span))
            used += span
        if bs_row:
            line += 1
    return cells


def _dash_bs_cell_classes(span, is_kpi, first):
    """The Bootstrap classes one served ``layout(bs)`` cell carries.

    Built only from *span* (an int, clamped 1-12 as ``_dash_bs_grid_cells``
    clamps it), *is_kpi* and *first* -- never from the cell's name -- so a
    hostile registered name cannot reach a class or the stylesheet
    (BR-10.8).  ``db-bs-cell`` and, on the first placed cell of each bs row,
    ``db-bs-first`` are read by ``_dash_bs_grid_css``'s stylesheet, which
    turns Bokeh's explicit grid placement into the saved page's flex-wrap
    reflow between 768 and 991 px; ``db-col-md-N``/``db-col-lg-N`` and, for
    a KPI card, ``db-cell-h-*`` are the saved page's own classes
    (``_render_bootstrap_html``), read by the same stylesheet's numbers.

    Args:
        span:   The cell's 12-column span at the large breakpoint.
        is_kpi: Whether the cell is a KPI card (a cell height class only
            applies to those, as on the saved page).
        first:  Whether this is the first placed cell of its bs row (a name
            ``_dash_bs_grid_cells`` dropped, or a repeat, is never first).

    Returns:
        A list of class names.
    """
    span = min(_DASH_BS_COLUMNS, max(1, int(span)))
    classes = ["db-bs-cell", "db-col-md-%d" % _md_span(span),
              "db-col-lg-%d" % span]
    if is_kpi:
        classes.append("db-cell-h-%s" % _cell_height_class(span))
    if first:
        classes.append("db-bs-first")
    return classes


def _dash_bs_grid_css():
    """The served ``layout(bs)`` grid's own stylesheet: the saved page's
    half rows and KPI cell heights, between 768 and 991 px wide.

    BokehJS writes a GridBox child's place as a ``:host`` rule inside the
    child's OWN shadow root (``parent_style``): a normal declaration, not
    ``!important``.  The child's host element sits inside the GRID's shadow
    root -- ``css_classes`` land on an element the grid's own stylesheet can
    select as ``:host > .cls`` -- and CSS Cascade Level 5 gives a normal
    rule from that OUTER encapsulation context precedence over one from the
    child's inner context, before specificity is even compared.  So a plain
    ``:host > .db-bs-cell { grid-row: auto; }`` on the grid overrides
    Bokeh's explicit placement without ``!important`` (measured 25sep2026,
    Bokeh 3.9.0, headless Chrome, through test/responsive_probe.py: a
    GridBox of span-3 KPI cards went from four across at every width to two
    per line at 768-991 px and back to four at 1440, with 130px cells).
    Built only from the module's own constants (BR-10.8); the result
    matches ``re.fullmatch(r"[\\w\\s:{}().;>,\\-!@/]+", css)``.

    Returns:
        The CSS text, appended to the grid's ``stylesheets`` as one
        ``InlineStyleSheet``.
    """
    below = _DASH_BS_LG_FROM_PX - 0.02
    parts = [
        "@media (min-width: %dpx) and (max-width: %.2fpx) { "
        ":host > .db-bs-cell { grid-row: auto; } "
        % (_DASH_BS_STACK_BELOW_PX, below)
    ]
    for n in range(1, _DASH_BS_COLUMNS + 1):
        parts.append(":host > .db-col-md-%d { grid-column: auto / span %d; } "
                     % (n, n))
    parts.append(":host > .db-bs-first { grid-column-start: 1; } } ")
    for k, px in _DASH_KPI_CELL_MIN_PX:
        parts.append(":host > .db-cell-h-%s { min-height: %dpx; } " % (k, px))
    narrow = _DASH_BS_STACK_BELOW_PX - 0.02
    parts.append(
        "@media (max-width: %.2fpx) { :host > .db-cell-h-sm, "
        ":host > .db-cell-h-md, :host > .db-cell-h-lg { min-height: %dpx; } }"
        % (narrow, _DASH_KPI_CELL_MIN_NARROW_PX))
    return "".join(parts)


def _dash_bs_grid(rows, cell_of, kpi_names=()):
    """The served ``layout(bs)`` grid: a GridBox of 12 equal columns.

    *rows* is what ``_dash_parse_bs_layout`` returns and *cell_of(name)* the
    renderable a registered name owns, or None -- ``_dash_layout_cell``, the
    resolver the other grids and the tab panels use.  Each renderable sits
    where ``_dash_bs_grid_cells`` puts it, which is where the saved page's
    markup puts it at its large breakpoint.  Unlike that markup it keeps
    those spans, narrowing, down to a 768 px window, and below that stacks
    every item into one column, as the saved page does (_dash_reflow;
    dash.sthlp says so).  Between 768 and 991 px it takes the saved page's
    md half rows and KPI cell minimum heights (WP-28 E14): each placed
    child carries the saved page's own classes (``_dash_bs_cell_classes``)
    and the grid carries one stylesheet built from them
    (``_dash_bs_grid_css``) that turns Bokeh's explicit placement into the
    same flex-wrap reflow the saved markup gets for free.

    A name with no renderable takes no columns, as the saved page leaves it
    out of its row.  A name the spec places twice keeps its first cell and
    the repeat draws nothing, its columns left empty: the saved page writes
    the same component twice, and Bokeh fills only the first element with
    that id.  A grid row that only repeats occupy is closed up, as a line of
    the saved page's empty copies of a graph has no height -- so however
    often a name is repeated, the grid has no more rows than items.  A
    figure keeps its own toolbar, as it does embedded on its own in the
    saved page -- this is not a gridplot.

    Args:
        rows:      ``[[(name, span), ...], ...]``.
        cell_of:   ``name -> renderable or None``; called once a name.
        kpi_names: Names that are KPI cards, for the cell-height class.

    Returns:
        The GridBox; it has no children when nothing could be placed.
    """
    from bokeh.models import GridBox, InlineStyleSheet
    cell = {}
    kept = []
    for bs_row in rows or []:
        keep = []
        for name, span in bs_row:
            if name not in cell:
                cell[name] = cell_of(name)
            if cell[name] is not None:
                keep.append((name, span))
        kept.append(keep)
    # Which bs row (index into `kept`) each cell _dash_bs_grid_cells emits
    # came from -- same nested order, so the k-th origin matches the k-th
    # cell -- so "first" (TR-10.7) can be decided per bs row, not per
    # wrapped grid line.
    origins = [ri for ri, bs_row in enumerate(kept) for _n, _s in bs_row]
    placed = []
    done = set()
    row_seen = set()
    for k, (name, r, c, r_span, c_span) in enumerate(_dash_bs_grid_cells(kept)):
        if name in done:
            continue
        done.add(name)
        ri = origins[k]
        first = ri not in row_seen
        row_seen.add(ri)
        placed.append((name, cell[name], r, c, r_span, c_span, first))
    line_of = {r: i for i, r in enumerate(sorted({p[2] for p in placed}))}
    children = []
    for name, m, r, c, r_span, c_span, first in placed:
        m.css_classes = list(m.css_classes) + _dash_bs_cell_classes(
            c_span, name in kpi_names, first)
        children.append((m, line_of[r], c, r_span, c_span))
    grid = _dash_reflow(GridBox(children=children,
                                cols=[_DASH_BS_TRACK] * _DASH_BS_COLUMNS,
                                spacing=_DASH_BS_GUTTER_PX,
                                sizing_mode="stretch_width"))
    grid.stylesheets = list(grid.stylesheets) + [
        InlineStyleSheet(css=_dash_bs_grid_css())]
    return grid


def _dash_header_fragments(title_text, subtitle_text):
    """The dashboard header as two HTML fragments, either possibly empty.

    Escaped exactly once here: callers pass RAW text.  The classes are the
    ones the scheme's ``css_block()`` styles; the served app used to emit
    one classless Div with a hard-coded grey subtitle.
    """
    t = (f'<h2 class="db-title" style="margin-bottom:2px;">'
         f'{html.escape(title_text)}</h2>' if title_text else "")
    s = (f'<p class="db-subtitle" style="margin-top:0;margin-bottom:8px;">'
         f'{html.escape(subtitle_text)}</p>' if subtitle_text else "")
    return t, s


def _dash_header_models(title_text, subtitle_text, css=""):
    """The header as Bokeh Divs, for the plain grid and the served app.

    *css* is the scheme's ``css_block()``; a Bokeh 3 Div renders inside a
    shadow root, so the rules are attached to the Div itself rather than
    relied on from the page head.
    """
    from bokeh.models import Div, InlineStyleSheet
    sheets = [InlineStyleSheet(css=css)] if css else []
    # disable_math: a Div runs its text through MathJax unless told not to,
    # and the escaped title/subtitle is not maths.  Without this a title
    # holding a TeX pair (`$$\href{javascript:...}{x}$$') is rendered by
    # MathJax, whose `html' package turns \href into a live <a>.
    return [Div(text=frag, sizing_mode="stretch_width",
                disable_math=True, stylesheets=list(sheets))
            for frag in _dash_header_fragments(title_text, subtitle_text)
            if frag]


# ---- Columns a layer's options name, and the mapper's metadata -------------------

#: Plot OPTIONS that name a dataset column the layer's source must carry.
#: The served app carried mlabel() and hover() and nothing else, so
#: `colorvar(foreign)' served drew the scheme colour: _apply_colorvar
#: returns when its column is absent from the source.
#: `wexp' is the weight variable of a `[aweight=price]' clause: dash.ado
#: writes it into the plot's options beside `weight' (the type), and naming
#: it here carries the column into the layer's source in both render modes
#: -- the standalone CDS through _collect_plot_vars, the served one through
#: _dash_layer_source's extra_cols -- so the mappers can read it.
_DASH_OPT_VAR_KEYS = ("colorvar", "mlabel", "wexp")
#: Plot KEYS that name a dataset column: one tuple for the saved column
#: lists, the served app and the embed plan (WP-29 P0.11).  The served
#: placeholder listed five of them, so a paired-coordinate layer's columns
#: were missing from it.
_DASH_PLOT_VAR_KEYS = ("yvar", "xvar", "var", "yvar1", "yvar2", "y1var",
                       "x1var", "y2var", "x2var")
#: The invisible swatch renderers a discrete colorvar() legend is built from.
_DASH_SWATCH_PREFIX = "_clegend_"


def _dash_mlabel_names(options):
    """``(first, extras)`` from a layer's mlabel() option.

    ``dash.ado`` validates mlabel() as one variable, so from a command it is
    always a single name.  A spec written by hand may carry several; the
    first is the label and the rest are named by ``_apply_mlabel_opts`` so
    that nothing is dropped in silence.  Read here, once, so that the
    column lists, the mappers that rebuild their source and the label
    applier agree on which name that is -- a source built for
    ``"make foreign"`` carried no column of that name, and the label
    applier then found nothing to draw.
    """
    names = str((options or {}).get("mlabel", "") or "").split()
    return (names[0] if names else ""), names[1:]


def _dash_option_columns(options, columns=None):
    """The columns a layer's options name -- colorvar() and mlabel() -- in
    ``_DASH_OPT_VAR_KEYS`` order, de-duplicated, restricted to *columns*
    when one is given."""
    out = []
    for key in _DASH_OPT_VAR_KEYS:
        if key == "mlabel":
            v = _dash_mlabel_names(options)[0]
        else:
            v = str((options or {}).get(key, "") or "").strip()
        if not v or v in out:
            continue
        if columns is not None and v not in columns:
            continue
        out.append(v)
    return out


def _dash_colorvar_domain(columns, options, mask=None, where=""):
    """The colour rows of a colorvar() layer: the values its key is drawn
    from (WP-29 P0.16).

    twoway draws a colorvar() key from the observations the plot draws --
    its own if/in, the graph's if/in and, under by(), its panel -- and
    counts an observation whose y or x is missing (measured in StataNow
    19.5, test/fixtures/colorvar_qualifier_truth.json).  The saved page
    passes the layer's source columns and the view's row mask; the served
    app passes the layer's frame before any missing x or y is dropped.

    A numeric or date column is read through ``_dash_float_values`` on the
    column object itself (a served date column is datetime64, which a list
    of Timestamps would refuse), so a date comes back in epoch
    milliseconds.  A column that cannot be read as numbers (a string
    variable) comes back as a list.

    Args:
        columns: A DataFrame or a ColumnDataSource ``.data`` dict.
        options: The layer's options; ``colorvar`` names the variable.
        mask:    A boolean flag per row, or None for every row.
        where:   Names the layer in the one warning this can give.

    Returns:
        A float array or a list, or None when there is no colorvar, its
        name is not a Stata name, the column is absent, or *mask* does not
        align with it (that case warns: the key is then drawn from every
        row).
    """
    var = str((options or {}).get("colorvar", "") or "").strip()
    if not var or not _dash_is_stata_name(var):
        return None
    try:
        col = columns[var]
    except (KeyError, TypeError, IndexError):
        return None
    sel = None
    if mask is not None:
        sel = np.asarray(mask, dtype=bool)
        if sel.shape != (len(col),):
            warnings.warn(
                f"dash: {where or 'a layer'}: its colour key could not be "
                f"restricted to its observations ({sel.size} flags for "
                f"{len(col)} rows); the key is drawn from every row.",
                UserWarning, stacklevel=2)
            return None
    try:
        vals = _dash_float_values(col)
    except (ValueError, TypeError):
        vals = col.tolist() if hasattr(col, "tolist") else list(col)
        if sel is None:
            return vals
        return [v for v, keep in zip(vals, sel) if keep]
    return vals if sel is None else vals[sel]


def _dash_colorvar_field(data, varname):
    """A name for a colorvar() layer's colour bins that no column holds
    (WP-29 P0.16).

    The first ``f"{_DASH_CVAR_PREFIX}{k}_{varname}"`` for k = 1, 2, ...
    that is not a key of *data*, so two colorvar layers on one source each
    keep their own bins, and no user variable can be overwritten: the
    loader refuses a variable under the reserved ``__dash`` prefix.

    Returns None when *varname* is not a Stata name.
    """
    if not _dash_is_stata_name(varname):
        return None
    keys = set(data.keys()) if hasattr(data, "keys") else set(data)
    for k in range(1, len(keys) + 2):
        name = f"{_DASH_CVAR_PREFIX}{k}_{varname}"
        if name not in keys:
            return name
    return None


def _dash_value_labels_for(var, value_labels, value_label_names):
    """The value labels of *var*, ``{code: text}``, or ``{}`` (TR-14.6,
    WP-28 S14 -- the one copy of the lookup ``GlyphMapper._mlabel_value_labels``
    and four other sites each wrote for themselves).

    Looked up by the label set's name first -- *value_label_names* maps
    the variable to it -- and then by the variable's own name, which is
    how real jsonio keys *value_labels* (measured: ``jsonio out ...
    metaprint(vallabs labelnames)`` writes ``{"r": {"0": "Zero"}}`` for a
    variable ``r`` carrying the label set ``rl``).

    Args:
        var: The variable's name, or ``""``/``None``.
        value_labels: ``{labelset: {code: text}}``, or keyed by the
            variable's own name, as real jsonio writes it; any non-dict
            (including ``None``) is read as empty.
        value_label_names: ``{varname: labelset}``; any non-dict read as
            empty.

    Returns:
        A dict, possibly empty; never anything else.
    """
    if not var:
        return {}
    value_labels = value_labels if isinstance(value_labels, dict) else {}
    value_label_names = (value_label_names
                         if isinstance(value_label_names, dict) else {})
    labelset = value_label_names.get(var, "")
    vlabels = value_labels.get(labelset, {}) if labelset else {}
    if not vlabels:
        vlabels = value_labels.get(var, {})
    return vlabels if isinstance(vlabels, dict) else {}


def _dash_var_label(var_labels, name, default=""):
    """The text twoway draws for variable *name*: its label when the label
    is not ``""``, otherwise the name (WP-29 P0.3).

    Measured in Stata 19 by SVG export (test/fixtures/unlabelled_truth.json,
    scripts/extract_unlabelled_truth.do): an unlabelled variable -- which
    Stata's exporter writes with the label ``""`` -- is drawn by its name as
    axis title, legend key and colour-key title.  A label of blanks is NOT
    empty and is drawn as given (E.svg), so the label is never stripped.

    Total: *default* when *name* is ``None`` or ``""``; ``str(name)`` for a
    name that is not text; the name when *var_labels* is not a mapping or
    holds a non-text label.  It raises nothing.

    Security: the result goes only to sinks that already carry arbitrary
    label text (canvas axis titles and keys, BokehJS tooltip text nodes);
    a name replacing an empty label adds no new sink.
    """
    if name is None or name == "":
        return default
    if not isinstance(name, str):
        return str(name)
    lab = (var_labels if isinstance(var_labels, dict) else {}).get(name)
    if isinstance(lab, str) and lab != "":
        return lab
    return name


def _dash_clean_var_labels(raw):
    """``variableLabels`` as both renderers keep it: text keyed by name.

    A label that is ``""`` (an unlabelled variable, as Stata's exporter
    writes it) or not text becomes the name, so any ``.get(v, v)`` reads
    twoway's rule (:func:`_dash_var_label`); a mapping that is not a dict
    is ``{}``, and a key that is not non-empty text is dropped.  Every
    variable keeps its key, so membership still tells the dataset's
    variables from computed columns.  A malformed map used to abort the
    build (a list: ``'list' object has no attribute 'get'``; an int, dict
    or null label: a Bokeh validation error) -- WP-29 P0.3.
    """
    if not isinstance(raw, dict):
        return {}
    return {k: (v if isinstance(v, str) and v != "" else k)
            for k, v in raw.items() if isinstance(k, str) and k}


def _dash_filter_base_title(label, var_labels, name):
    """A filter widget's title before :func:`_dash_filter_title` adds its
    inequality: ``label()``, else the variable's label, else the name.

    A text of blanks counts as absent here (the saved page's documented
    chain), unlike :func:`_dash_var_label`, which draws a label of blanks
    as given.  Not ``_dash_filter_label``: that name is the ``filter()``
    option parser.  The served app used to pass the raw ``""`` label of an
    unlabelled variable, which titled its widget ``""`` (WP-29 P0.3).
    Security: a Select title is a text node and a slider title still passes
    ``_dash_inert_tex`` in ``_dash_filter_title``.
    """
    vl = var_labels if isinstance(var_labels, dict) else {}
    return (str(label or "").strip()
            or str(vl.get(name, "") or "").strip()
            or str(name))


def _dash_attach_labels(mapper, variable_labels=None, value_labels=None,
                        value_label_names=None, date_vars=None,
                        numeric_formats=None, storage_types=None,
                        formats=None):
    """Give *mapper* the dataset's Stata metadata, in either render mode.

    ``_apply_colorvar`` reads value labels for the colour key and the
    variable label for its title; ``_apply_mlabel_opts`` reads date and
    numeric formats.  The served app built its mapper at module level and
    attached none of these, so a served colour key would have read "0"/"1"
    where the saved one reads "Domestic"/"Foreign".
    """
    mapper.variable_labels = (variable_labels if variable_labels is not None
                              else {})
    mapper.value_labels = value_labels if value_labels is not None else {}
    mapper.value_label_names = (value_label_names
                                if value_label_names is not None else {})
    mapper.date_vars = dict(date_vars or {})
    mapper.numeric_formats = dict(numeric_formats or {})
    mapper.storage_types = dict(storage_types or {})
    # Every display format, date pictures included (WP-28 S12): marker
    # labels and the colour key write a variable's own text.
    mapper.formats = dict(formats or {})
    return mapper


def _dash_is_swatch(renderer):
    """Is *renderer* one of a discrete colorvar() legend's invisible swatches?
    They are on the figure so the Legend can show a colour; they are not a
    series key and not a source to refresh or redraw on a filter move."""
    return str(getattr(renderer, "name", "") or "").startswith(
        _DASH_SWATCH_PREFIX)


# ---- The dashboard's confidence level ------------------------------------------

def _dash_session_level(build_options, default=_DEFAULT_LEVEL):
    """The dashboard's confidence level: c(level) as dash.ado serialised it.

    A per-plot level() overrides this in ``_resolve_level``; an absent,
    blank, non-numeric or out-of-range value falls back to Stata's factory
    95 with a warning, in BOTH modes.  The served app used to read it,
    unvalidated, for the legend key and not at all for the band -- so a
    served lfitci under `set level 90' drew a 95% band labelled "90% CI".
    """
    raw = str((build_options or {}).get("level", "") or "").strip()
    if not raw:
        return float(default)
    try:
        val = float(raw)
    except ValueError:
        warnings.warn(
            f"dash: could not read the confidence level {raw!r}; "
            f"using {default}.", UserWarning, stacklevel=2)
        return float(default)
    if not (0.0 < val < 100.0):
        warnings.warn(
            f"dash: c(level) of {raw} is outside (0, 100); using {default}.",
            UserWarning, stacklevel=2)
        return float(default)
    return val



# ---- Sub-options: honour, or name ------------------------------------------
#
# dash.sthlp: "Nothing is ever dropped without being named."  It held for
# options (the ignoring note) and, since WP-11, for by()'s sub-options; it
# did not hold for the sub-options of legend(), xlabel()/ylabel(),
# xscale()/yscale(), the textbox options, xline()/yline() or filter().
# Measured 22sep2026, every one of those rendered with no warning in either
# mode.  One report, in by()'s words, from code both modes run.

def _dash_report_suboptions(option, tokens, seen=None, key=""):
    """Name the sub-options of *option* dash does not implement.

    Once per graph per render: the figure body runs once per by() panel,
    and *seen* -- a set the caller keeps for the render -- stops the same
    report repeating per panel.  *key* is the graph's name.
    """
    toks = [t for t in tokens if t]
    if not toks:
        return
    if seen is not None:
        mark = (key, option, tuple(toks))
        if mark in seen:
            return
        seen.add(mark)
    warnings.warn(
        "dash: %s() sub-option(s) not implemented and ignored: %s"
        % (option, " ".join(toks)), UserWarning, stacklevel=2)


def _dash_subopt_name(tok):
    """``holes(1)`` -> ``holes``; ``span`` -> ``span``."""
    return tok.split("(", 1)[0].strip().lower()


# ==== twoway's sub-option tables (WP-30 P1.19) ===========================
# Each row is (full, minimum, stage, kind, star, check): *stage* the parse
# order, *kind* "w" a word, "a" an argument taken once per stage, "r" a
# repeatable argument; *star* whether that stage's syntax has ``*`` (passes
# what it does not take on); *check* "" or "N1"/"NL" (a numlist) or "R"/"I"
# (a real/integer literal).  The minimum is the capitalised prefix in
# StataNow 19.5's ado/base parsers; a name matches in lower case only.

